fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle"; fail=1; }
exit $fail
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle new"; fail=1; }
for f in app/forms/*.form; do bash bin/render "$(basename "$f" .form)" | grep -q 'action="?/' && { echo "slash in query key: $f"; fail=1; }; done
exit $fail
